import React from 'react';
import { CheckCircle2, AlertTriangle, ShieldCheck } from 'lucide-react';

const SkillBadge = ({ skill, type = 'matched', evidence }) => {
  const isMatched = type === 'matched';
  const isVerified = type === 'verified';

  if (isVerified) {
    return (
      <span className="inline-flex items-center space-x-1.5 px-3 py-1.5 rounded-full text-xs font-mono font-semibold bg-scifi-600/25 text-scifi-100 border border-scifi-600/50 shadow-purple-glow transition-transform hover:scale-105">
        <ShieldCheck className="w-3.5 h-3.5 text-scifi-200" />
        <span>{skill}</span>
        {evidence && <span className="text-[10px] text-scifi-200/80 font-normal">({evidence})</span>}
      </span>
    );
  }

  return (
    <span
      className={`inline-flex items-center space-x-1.5 px-3 py-1.5 rounded-full text-xs font-mono font-semibold transition-all duration-200 hover:scale-105 ${
        isMatched
          ? 'bg-scifi-600/20 text-scifi-100 border border-scifi-600/40 shadow-deep-glow'
          : 'bg-scifi-800/80 text-scifi-200 border border-scifi-600/30'
      }`}
    >
      {isMatched ? (
        <CheckCircle2 className="w-3.5 h-3.5 text-scifi-200" />
      ) : (
        <AlertTriangle className="w-3.5 h-3.5 text-scifi-400" />
      )}
      <span>{skill}</span>
    </span>
  );
};

export default SkillBadge;
